import{describe,it,expect}from"vitest";import{heritageLocations,setSliderPosition}from"../../frontend/then-vs-now/then-vs-now.js";describe("Then vs Now Heritage Comparison Explorer",()=>{it("contains minimum 10 heritage locations with complete metadata",()=>{expect(Array.isArray(heritageLocations)).toBe(!0),expect(heritageLocations.length).toBeGreaterThanOrEqual(10),heritageLocations.forEach(e=>{expect(e.id).toBeDefined(),expect(e.title).toBeDefined(),expect(e.location).toBeDefined(),expect(e.category).toBeDefined(),expect(e.thenYear).toBeDefined(),expect(e.nowYear).toBeDefined(),expect(e.thenDescription).toBeDefined(),expect(e.nowDescription).toBeDefined(),expect(e.conservationStatus).toBeDefined()})}),it("clamps slider position calculations between 0 and 100",()=>{expect(()=>setSliderPosition(50)).not.toThrow(),expect(()=>setSliderPosition(-15)).not.toThrow(),expect(()=>setSliderPosition(120)).not.toThrow()}),it("covers key categories like monument, temple, and colonial",()=>{const e=new Set(heritageLocations.map(e=>e.category));expect(e.has("monument")).toBe(!0),expect(e.has("temple")).toBe(!0),expect(e.has("colonial")).toBe(!0)})});